input.command:
$ErrorActionPreference='Stop'
$o = Import-Csv inputs/orders.csv
$r = Import-Csv inputs/refunds.csv

# orders: dedupe exact, then latest revision per order_id
$odup = $o | Group-Object { $_.order_id + '|' + $_.revision }
$exactDupO = ($odup | ForEach-Object { $_.Count - 1 } | Measure-Object -Sum).Sum
$olatest = $odup | ForEach-Object { $_.Group[0] } | Group-Object order_id | ForEach-Object { $_.Group | Sort-Object {[int]$_.revision} -Descending | Select-Object -First 1 }
$supersededO = $o.Count - $exactDupO - $olatest.Count

$rdup = $r | Group-Object { $_.refund_id + '|' + $_.revision }
$exactDupR = ($rdup | ForEach-Object { $_.Count - 1 } | Measure-Object -Sum).Sum
$rlatest = $rdup | ForEach-Object { $_.Group[0] } | Group-Object refund_id | ForEach-Object { $_.Group | Sort-Object {[int]$_.revision} -Descending | Select-Object -First 1 }
$supersededR = $r.Count - $exactDupR - $rlatest.Count

$includedStatuses = @('paid','shipped')
$includedById = @{}
$ledger = foreach ($ord in ($olatest | Sort-Object order_id)) {
    $inc = $includedStatuses -contains $ord.status
    if ($inc) { $includedById[$ord.order_id] = $ord }
    $succ = 0
    if ($inc) {
        $succ = ($rlatest | Where-Object { $_.order_id -eq $ord.order_id -and $_.status -eq 'success' } | ForEach-Object { [int]$_.amount_cents } | Measure-Object -Sum).Sum
        if (-not $succ) { $succ = 0 }
    }
    [pscustomobject]@{
        order_id = $ord.order_id; customer_group = $ord.customer_group; status = $ord.status
        gross_cents = [int]$ord.gross_cents; successful_refund_cents = [int]$succ
        net_cents = if ($inc) { [int]$ord.gross_cents - [int]$succ } else { 0 }
        included = if ($inc) { 'true' } else { 'false' }
    }
}

$orphan = @($rlatest | Where-Object { $_.status -eq 'success' -and -not $includedById.ContainsKey($_.order_id) -and -not ($olatest | Where-Object order_id -eq $_.order_id) } | ForEach-Object refund_id | Sort-Object)
$nonSucc = @($rlatest | Where-Object { $_.status -ne 'success' } | ForEach-Object refund_id | Sort-Object)
$inelig = @($rlatest | Where-Object { $_.status -eq 'success' -and ($olatest | Where-Object order_id -eq $_.order_id) -and -not $includedById.ContainsKey($_.order_id) } | ForEach-Object refund_id | Sort-Object)

$incLedger = $ledger | Where-Object included -eq 'true'
$total = [pscustomobject]@{ order_count=$incLedger.Count; gross_cents=($incLedger|Measure-Object gross_cents -Sum).Sum; refund_cents=($incLedger|Measure-Object successful_refund_cents -Sum).Sum; net_cents=($incLedger|Measure-Object net_cents -Sum).Sum }
$groups = $incLedger | Group-Object customer_group | Sort-Object Name | ForEach-Object {
    [pscustomobject]@{ customer_group=$_.Name; order_count=$_.Count; gross_cents=($_.Group|Measure-Object gross_cents -Sum).Sum; refund_cents=($_.Group|Measure-Object successful_refund_cents -Sum).Sum; net_cents=($_.Group|Measure-Object net_cents -Sum).Sum }
}

"expected ledger:"; $ledger | Format-Table -AutoSize | Out-String
"expected aggregate:"; [pscustomobject]@{total=$total; groups=$groups} | ConvertTo-Json -Depth 5
"expected exceptions:"; [pscustomobject]@{ exact_duplicate_order_rows=$exactDupO; superseded_order_rows=$supersededO; exact_duplicate_refund_rows=$exactDupR; superseded_refund_rows=$supersededR; orphan_refund_ids=$orphan; ignored_non_success_refund_ids=$nonSucc; ignored_ineligible_order_refund_ids=$inelig } | ConvertTo-Json -Depth 5

"--- file checks ---"
"actual aggregate:"; Get-Content outputs/aggregate.json -Raw
"actual exceptions:"; Get-Content outputs/exceptions.json -Raw
"actual ledger:"; Get-Content outputs/order_ledger.csv -Raw
"ledger rows: $((Import-Csv outputs/order_ledger.csv).Count), unique ids: $((Import-Csv outputs/order_ledger.csv | Select-Object -ExpandProperty order_id -Unique).Count)"
